"use client";

import React, { useEffect, useState } from "react";
import Header from "@/components/common/Header";
import Navbar from "@/components/common/Navbar";
import Footer from "@/components/common/Footer";
import { fetchCartItems } from "@/services/cartService";
import OrderSummary from "@/components/checkout/OrderSummary";
import DetailPayment from "@/components/checkout/DetailPayment";
import AddressComponent from "@/components/checkout/AddressComponent";

interface CartItem {
  cartItemId: number;
  quantity: number;
  totalAmount: number;
  cartId: number;
  productId: number;
  productName: string;
  productImage: string;
  productPrice: number;
}

const CheckoutPage = () => {
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const accessToken = typeof window !== "undefined" ? localStorage.getItem("token") : null;

  useEffect(() => {
    const getCartData = async () => {
      try {
        const data = await fetchCartItems(accessToken);
        setCartItems(data.length ? data : []);
      } catch (err: any) {
        if (err.response?.data?.message === "Item not found !") {
          setCartItems([]);
        } else {
          setError(err.message);
        }
      } finally {
        setLoading(false);
      }
    };
    getCartData();
  }, [accessToken]);

  const subtotal = cartItems.reduce((acc, item) => acc + (item.totalAmount || 0), 0);
  const shippingFee = 20000
  const totalPrice = subtotal + shippingFee;

  return (
    <div className="min-h-screen flex flex-col">
      <Header />
      <Navbar />
      <main className="flex-1 container mx-auto p-6 mt-8 mb-8">
        <h1 className="text-3xl font-bold mb-4 text-black">Checkout</h1>

        {/* Address Component */}
        <AddressComponent />

        {loading && <p>Loading cart items...</p>}
        {error && <p className="text-red-500">{error}</p>}
        {!loading && !error && cartItems.length === 0 && <p>Your cart is empty.</p>}

        {cartItems.length > 0 && (
          <div className="flex flex-col md:flex-row gap-6">
            {/* Order Summary Section */}
            <div className="md:w-2/3">
              <OrderSummary cartItems={cartItems} />
            </div>

            {/* Payment Details Section */}
            <div className="md:w-1/3">
              <DetailPayment subtotal={subtotal} shippingFee={shippingFee} totalPrice={totalPrice} />
            </div>
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default CheckoutPage;
