"use client";

import React, { useEffect, useState } from "react";
import axios from "axios";
import { getAccessToken } from "@/lib/utils/auth";

const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL;

interface Address {
  id: number;
  label: string;
  addressDetail: string;
  note?: string;
  isMain: boolean;
}

const AddressComponent = () => {
  const [defaultAddress, setDefaultAddress] = useState<Address | null>(null);
  const [addresses, setAddresses] = useState<Address[]>([]);
  const [showPopup, setShowPopup] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const accessToken = getAccessToken();

  useEffect(() => {
    if (!accessToken) return;

    const fetchUserAddresses = async () => {
      try {
        const response = await axios.get(`${API_BASE_URL}/addresses`, {
          headers: { Authorization: `Bearer ${accessToken}` },
        });

        if (response.data.length === 0) {
          setError("No addresses found.");
          setLoading(false);
          return;
        }

        // Find the main (default) address
        const mainAddress = response.data.find((addr: Address) => addr.isMain);

        if (mainAddress) {
          fetchDefaultAddress(mainAddress.id);
        } else {
          setError("No default address found.");
          setLoading(false);
        }
      } catch (err: any) {
        console.error("Failed to fetch addresses: ", err.response?.data?.message || err.message);
        setError("Failed to fetch addresses");
        setLoading(false);
      }
    };

    const fetchDefaultAddress = async (addressId: number) => {
      try {
        const response = await axios.get(`${API_BASE_URL}/addresses/user-address`, {
          params: { addressId },
          headers: { Authorization: `Bearer ${accessToken}` },
        });

        setDefaultAddress(response.data);
      } catch (err: any) {
        console.error("Failed to fetch default address: ", err.response?.data?.message || err.message);
        setError("Failed to fetch default address");
      } finally {
        setLoading(false);
      }
    };

    fetchUserAddresses();
  }, [accessToken]);

  const fetchAllAddresses = async () => {
    try {
      const response = await axios.get(`${API_BASE_URL}/addresses`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      setAddresses(response.data);
    } catch (err: any) {
      console.error("Failed to fetch all addresses: ", err.response?.data?.message || err.message);
      setError("Failed to fetch all addresses");
    }
  };

  const handleChangeAddress = () => {
    setShowPopup(true);
    fetchAllAddresses();
  };

  const handleSelectAddress = (address: Address) => {
    setDefaultAddress(address);
    setShowPopup(false);
  };

  if (loading) return <p>Loading address...</p>;
  if (error) return <p className="text-red-500">{error}</p>;

  return (
    <div className="p-4 bg-white shadow-md rounded-lg mb-4">
      <h2 className="text-lg font-bold">Shipping Address</h2>
      {defaultAddress ? (
        <div>
          <p className="font-semibold">{defaultAddress.label}</p>
          <p className="text-gray-600">{defaultAddress.addressDetail}</p>
          {defaultAddress.note && <p className="text-gray-500 text-sm">{defaultAddress.note}</p>}
          <button 
            className="mt-2 px-4 py-2 bg-blue-500 text-white rounded-lg" 
            onClick={handleChangeAddress}
          >
            Change Address
          </button>
        </div>
      ) : (
        <p>No address found.</p>
      )}

      {showPopup && (
        <div className="fixed inset-0 flex items-center justify-center bg-gray-900 bg-opacity-50">
          <div className="bg-white p-6 rounded-lg w-96">
            <h3 className="text-lg font-semibold mb-4">Select Address</h3>
            {addresses.map((address) => (
              <div key={address.id} className="p-3 border-b border-gray-300">
                <p className="font-semibold">{address.label}</p>
                <p className="text-gray-600">{address.addressDetail}</p>
                {address.note && <p className="text-gray-500 text-sm">{address.note}</p>}
                <button 
                  className="mt-2 px-4 py-2 bg-green-500 text-white rounded-lg" 
                  onClick={() => handleSelectAddress(address)}
                >
                  Choose Address
                </button>
              </div>
            ))}
            <button 
              className="mt-4 px-4 py-2 bg-red-500 text-white rounded-lg w-full"
              onClick={() => setShowPopup(false)}
            >
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AddressComponent;
