import React from "react";
import Image from "next/image";
import { formatCurrency } from "@/lib/utils/formatCurrency";

interface CartItem {
  cartItemId: number;
  productName: string;
  productImage: string;
  productPrice: number;
  quantity: number;
}

interface OrderSummaryProps {
  cartItems: CartItem[];
}

const OrderSummary: React.FC<OrderSummaryProps> = ({ cartItems }) => {
  return (
    <div className="p-6 rounded-lg shadow-lg bg-gray-100">
      <h2 className="text-xl font-semibold mb-4 text-black">Order Summary</h2>
      {cartItems.map((item) => (
        <div key={item.cartItemId} className="flex items-center border-b border-gray-300 pb-4 mb-4">
          <Image src={item.productImage || "/images/default-product.jpg"} alt={item.productName} width={80} height={80} className="rounded-lg" />
          <div className="ml-4 flex-1">
            <h3 className="text-lg font-semibold text-black">{item.productName}</h3>
            <p className="text-gray-700">{formatCurrency(item.productPrice)} x {item.quantity}</p>
          </div>
        </div>
      ))}
    </div>
  );
};

export default OrderSummary;
